def word_lengths(sentence):
    # 'the quick  fox' -> 'the=3 quick=5 fox=3'
    parts = [f'{w}={len(w)}' for w in sentence.split()]
    return ' '.join(parts)

print(word_lengths('the quick  fox'))  # the=3 quick=5 fox=3
print(repr(word_lengths('   ')))      # ''

