def caesar_shift(text, k):
    out = []
    for ch in text:
        if 'a' <= ch <= 'z':
            base = ord('a')
        elif 'A' <= ch <= 'Z':
            base = ord('A')
        else:
            out.append(ch)
            continue
        out.append(chr((ord(ch) - base + k) % 26 + base))
    return ''.join(out)

